CREATE TABLE public.ai_explanation_access_state (id text PRIMARY KEY CHECK (id = 'football-explanations'), message text NOT NULL, status integer NOT NULL CHECK (status = 403), updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.ai_explanation_access_state TO service_role; ALTER TABLE public.ai_explanation_access_state ENABLE ROW LEVEL SECURITY; COMMENT ON TABLE public.ai_explanation_access_state IS 'Server-only persistent provider denial circuit breaker; no browser access.';